func (d *DefaultNode) PullImage(ctx context.Context) error {
	for imageKey, imageName := range d.OverwriteNode.GetImages(ctx) {
		if imageName == "" {
			return fmt.Errorf(
				"missing required %q attribute for node %q",
				imageKey,
				d.Cfg.ShortName,
			)
		}
		err := d.Runtime.PullImage(ctx, imageName, d.Config().ImagePullPolicy)
		if err != nil {
			return err
		}
	}
	return nil
}

func (d *DefaultNode) VerifyHostRequirements() error {
	return d.HostRequirements.Verify(d.Cfg.Kind, d.Cfg.ShortName)
}

func (d *DefaultNode) Deploy(ctx context.Context, _ *DeployParams) error {
	// Set the "CLAB_INTFS" variable to the number of interfaces (endpoints) a node has.
	// This env var does not count in the eth0 interface that is automatically created by the
	// container runtime. This env var is used by some containers (e.g. vrnetlab systems) to
	// postpone the startup until all interfaces
	// have been added to the container namespace.
	d.Config().Env[clabconstants.ClabEnvIntfs] = strconv.Itoa(len(d.GetEndpoints()))

	// create the container
	cID, err := d.Runtime.CreateContainer(ctx, d.Cfg)
	if err != nil {
		return err
	}

	// start the container
	_, err = d.Runtime.StartContainer(ctx, cID, d)
	if err != nil {
		return err
	}

	// Update the nodes state
	d.SetState(clabnodesstate.Deployed)

	return nil
}

// GetNSPath retrieves the nodes nspath.
func (d *DefaultNode) GetNSPath(ctx context.Context) (string, error) {
	var err error
	nsp := ""

	if d.Cfg.IsRootNamespaceBased {
		netns, err := ns.GetCurrentNS()
		if err != nil {
			return "", err
		}
		nsp = netns.Path()
	}
	if nsp == "" {
		nsp, err = d.Runtime.GetNSPath(ctx, d.OverwriteNode.GetContainerName())
		if err != nil {
			log.Errorf("Unable to determine NetNS Path for node %s: %v", d.Cfg.ShortName, err)
			return "", err
		}
	}

	return nsp, err
}

// ShouldSkipLifecycle reports whether lifecycle operations should no-op for this node.
func (d *DefaultNode) ShouldSkipLifecycle() bool {
	return d.Cfg.IsRootNamespaceBased || d.Cfg.AutoRemove
}

// LinkApplyMode returns the conservative default for node kinds that do not
// explicitly opt into live hotplug or restart handling.
func (d *DefaultNode) LinkApplyMode(ctx context.Context) LinkApplyMode {
	if d.Cfg != nil && (d.Cfg.IsRootNamespaceBased || d.Cfg.SkipUniquenessCheck) {
		return LinkApplyModeLive
	}
	return d.ImageLinkApplyMode(ctx, LinkApplyModeRecreate)
}

// ImageLinkApplyMode allows node kinds to keep their normal fallback behavior
// while opting into live link apply when their image declares support for it.
func (d *DefaultNode) ImageLinkApplyMode(
	ctx context.Context,
	fallback LinkApplyMode,
) LinkApplyMode {
	if d.imageHasBoxenVendorLabel(ctx) {
		return LinkApplyModeLive
	}

	return fallback
}

func (d *DefaultNode) imageHasBoxenVendorLabel(ctx context.Context) bool {
	if d == nil || d.Cfg == nil || d.Cfg.Image == "" {
		return false
	}

