			)
			return nil
		}

		if restoreErr := d.RestoreEndpoints(ctx); restoreErr != nil {
			return errors.Join(
				fmt.Errorf("node %q failed stopping container: %w", cfg.ShortName, err),
				fmt.Errorf("failed to restore endpoints: %w", restoreErr),
